#!/usr/bin/env bash
# ============================================================================
# VideoMind rebuild, Part 4a: transcription of recordings of any length
# ============================================================================
# FOR THE rebuild BRANCH ONLY. It refuses to run on main.
#
# Until now the whole video file went to OpenAI in one request, and
# OpenAI takes at most 25 MB, so anything longer than a few minutes was
# refused. A request that hung could also hold a job for half an hour.
#
# After this part:
#   * the sound is taken out of the video once with FFmpeg, as small
#     mono audio (about 21 MB an hour), and kept in storage next to the
#     original. FFmpeg reads the original through a signed address, so
#     nothing is copied to the server
#   * the sound is cut into pieces of about ten minutes, each ending in
#     a pause, so no sentence is cut in two. Each piece is about 4 MB
#   * each piece goes to whisper-1 with word and segment timing, and
#     with the end of the text before it as context
#   * each piece is saved the moment it comes back. A restart, a deploy
#     or Render putting the service to sleep only repeats the piece that
#     was in progress
#   * the transcript keeps every word with its time in the video, for
#     captions and the workspace later. Pages get sentences only; words
#     are sent when asked for (?words=1). Library lists leave
#     transcripts out, which makes them much lighter
#   * while a long recording is transcribed, its page says which piece
#     is being worked on ("Part 3 of 7")
#   * a video with no sound, or no speech, is ready with an empty
#     transcript and no analysis, instead of failing
#   * the 25 MB limit is gone. Recordings up to 4 hours are transcribed
#     (TRANSCRIBE_MAX_HOURS). Videos refused earlier for being over 25 MB
#     are queued again by the migration and transcribed after the deploy
#   * a transcription request that hangs is cut off after 5 minutes
#
#   BACKEND   1 new file, 9 changed. Database migration 007_transcription
#             runs by itself at startup. No new packages.
#   FRONTEND  4 changed. No new packages.
#
#   ./vm_transcribe.sh            apply (needs Part 3c on the branch)
#   ./vm_transcribe.sh --force    apply even if local files differ from GitHub
#   ./vm_transcribe.sh --revert   restore everything from the latest backup
#
# Run from the repo root (dir containing backend/ and frontend/).
# ============================================================================
set -euo pipefail

MARKER="vm_transcribe"
STAMP="$(date +%Y%m%d-%H%M%S)"
BAKDIR=".vm_transcribe_backups"

ADD=(
  "backend/src/services/transcribe.ts"
)
MOD=(
  "backend/.env.example"
  "backend/src/lib/assets.ts"
  "backend/src/lib/media.ts"
  "backend/src/lib/migrations.ts"
  "backend/src/lib/store.ts"
  "backend/src/routes/videos.ts"
  "backend/src/services/aiPipeline.ts"
  "backend/src/services/pipeline.ts"
  "backend/src/types/video.ts"
  "frontend/src/app/video/[id]/page.tsx"
  "frontend/src/components/upload/UploadZone.tsx"
  "frontend/src/components/video/ProcessingStatus.tsx"
  "frontend/src/lib/api.ts"
)
PRE_MOD=(
  "1eddfc438deee94663749b638e7a7eb07ddde81208dd2488943fcd58dfb754ef"
