B64_A0
verify "$TMPD/a0" "${NEW_ADD[0]}" "backend/src/services/transcribe.ts"

grep -q "$MARKER" "$TMPD/a0"                       || die "transcribe.ts payload missing marker. Aborting."
grep -q '007_transcription' "$TMPD/m3"           || die "migrations.ts payload missing migration 007. Aborting."
grep -q '006_media' "$TMPD/m3"                   || die "migrations.ts payload lost migration 006. Aborting."
grep -q 'extractSound' "$TMPD/m2"                || die "media.ts payload missing sound extraction. Aborting."
grep -q 'format_whitelist' "$TMPD/m2"            || die "media.ts payload lost the format limit. Aborting."
grep -q 'transcribeLong' "$TMPD/m7"            || die "pipeline.ts payload missing the new transcription. Aborting."
grep -q 'INSPECT' "$TMPD/m7"                   || die "pipeline.ts payload lost the thumbnail job. Aborting."
if grep -q 'TRANSCRIBE_MAX_BYTES' "$TMPD/m7"; then die "pipeline.ts payload still has the 25 MB limit. Aborting."; fi
grep -q 'timestamp_granularities: \["word", "segment"\]' "$TMPD/m6" || die "aiPipeline.ts payload does not ask for word timing. Aborting."
grep -q 'canView' "$TMPD/m5"                     || die "videos.ts payload lost the private check. Aborting."
grep -q 'pictureUrl' "$TMPD/m5"                  || die "videos.ts payload lost the thumbnails. Aborting."
grep -q 'ResumableUpload' "$TMPD/m10"            || die "UploadZone.tsx payload lost the upload. Aborting."
grep -q 'retryVideoJob' "$TMPD/m11"              || die "ProcessingStatus.tsx payload lost the retry. Aborting."
say "14 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in "${ADD[@]}"; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in "${ADD[@]}"; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in "${ADD[@]}"; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied transcription of recordings of any length (rebuild Part 4a)."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit) && (cd frontend && npx tsc --noEmit && npm run build)"
say "Undo: ./vm_transcribe.sh --revert"
